std::string LangText(const std::string& en) {
    int lang = (int)STR::DefaultLangCode - 1; // 0..19 (STRLangCode order, see header)
    if (lang >= 0 && lang < 20) {
        for (const Entry& e : Texts) {
            if (en != e.En) continue;
            const char* t = e.T[lang];
            if (t != nullptr && *t != '\0') return ToLatin1(t);
            break; // no translation for this language: the English original
        }
    }
    return en;
}

